}

#include        "../system/runConditions"

dimensions      [0 1 -1 0 0 0 0];

internalField   uniform ($flowVelocity 0 0);

boundaryField
{
    inlet
    {

        type       prescribedPipeInlet;

        approximationType exponential;

        R	$Rpipe;

